/* @lc app=leetcode id=3164 lang=kotlin */ class Solution { fun numberOfPairs(nums1: IntArray, nums2: IntArray, k: Int): Long = (nums1.maxOrNull() ?: 0).let { max1 -> HashMap<Int, Long>().apply { nums1.forEach { this[it] = (this[it] ?: 0L) + 1L } }.let { freq1 -> HashMap<Int, Long>().apply { nums2.forEach { this[it] = (this[it] ?: 0L) + 1L } }.entries.sumOf { (v, count2) -> (v.toLong() * k).let { step -> if (step > max1 || step == 0L) 0L else generateSequence(step) { if (it + step <= max1) it + step else null }.sumOf { m -> (freq1[m.toInt()] ?: 0L) * count2 } } } } } }